"""Раздел 1. Состояние вопроса и задачи исследования."""


def build(doc, D):
    doc.h1(1, "Состояние вопроса и задачи исследования")

    doc.h2("1.1", "Электрификация мобильных энергетических средств сельскохозяйственного назначения")
    doc.p("Электрификация трактора развивается по трём направлениям, различающимся схемой силовой установки: электрификация отдельных "
          "потребителей (вентилятор, насос, вал отбора мощности) при сохранении дизельного двигателя; гибридные силовые "
          "установки последовательной и параллельной схем; полностью электрические машины с бортовым накопителем энергии "
          "[@moreda2016,scolaro2021]. В обзоре [@moreda2016] показано, что основной причиной электрификации "
          "является не столько замена энергоносителя, сколько возможность точного управления рабочими органами и "
          "повышения коэффициента полезного действия передачи энергии, тогда как основным ограничением остаётся удельная "
          "энергоёмкость аккумуляторных батарей, на порядок уступающая дизельному топливу даже с учётом КПД двигателя "
          "внутреннего сгорания. Обзор [@scolaro2021] подтверждает этот вывод для современного состояния техники и "
          "указывает, что полностью электрические тракторы экономически оправданы прежде всего в классах малой мощности "
          "и на операциях с умеренной продолжительностью непрерывной работы.")
    doc.p("Количественные оценки энергетического эффекта электрификации получены преимущественно расчётным путём. В работе "
          "[@lajunen2024] методом имитационного моделирования в среде Autonomie сопоставлены тракторы с дизельной, "
          "гибридными, водородной (на топливных элементах) и аккумуляторной силовыми установками на двух циклах почвообработки и транспортном "
          "цикле; для аккумуляторной схемы потенциал снижения энергопотребления составил 60–70 %. Экспериментальные данные "
          "по опытному электротрактору приведены в [@ueka2013]: при движении и фрезеровании расход энергии снизился "
          "приблизительно на 70 % по сравнению с исходным трактором. Для гибридной параллельной схемы в [@mocera2020] "
          "показана возможность уменьшения номинальной мощности двигателя без ухудшения тяговых показателей за счёт "
          "кратковременной работы электрической машины в двигательном режиме. Обзор [@ghobadpour2019] рассматривает беспилотные "
          "машины с питанием от возобновляемых источников и подчёркивает, что эффект электрификации определяется не только "
          "машиной, но и источником электроэнергии.")
    doc.p("Экономическая сторона вопроса исследована в работах [@lagnelov2021c,lagnelov2021l]. На примере беспилотных "
          "тракторов мощностью 50 кВт с аккумуляторными батареями показано, что при учёте старения батареи и потерь от "
          "несвоевременного выполнения работ годовые затраты могут быть равны затратам парка дизельных тракторов с "
          "трактористами или ниже их [@lagnelov2021c]; при оценке жизненного "
          "цикла снижение выбросов парниковых газов определяется структурой генерации электроэнергии [@lagnelov2021l]. "
          "Существенно, что в указанных работах положительный экономический эффект достигается в том числе за счёт "
          "исключения тракториста, т. е. за счёт фактора, не связанного с энергоносителем.")
    doc.p("Таким образом, в литературе сложились три устойчивых положения: электрическая тяга обеспечивает кратное "
          "снижение энергии, подводимой к машине; её экологический эффект зависит от энергосистемы; экономическая "
          "целесообразность определяется соотношением цен на энергоносители, стоимостью батареи и интенсивностью "
          "использования машины. Вместе с тем большинство количественных оценок получено моделированием тракторов "
          "средней и большой мощности, а полевые данные по электротракторам малой мощности, работающим с серийными "
          "почвообрабатывающими машинами, в доступных источниках единичны.")

    doc.h2("1.2", "Особенности агрегатов тягового класса 0,6 при мелкой обработке почвы")
    doc.p("Тяговый класс 0,6 по ГОСТ 27021 [@gost27021] объединяет тракторы с номинальным тяговым усилием от 5,4 до 8,1 кН. "
          "Машины этого класса работают преимущественно с навесными орудиями шириной захвата 1,0–1,5 м: "
          "культиваторами, фрезами, косилками, опрыскивателями. Для энергетической оценки принципиально различие "
          "между тяговыми и тягово-приводными агрегатами. У культиватора вся мощность передаётся через движители и "
          "расходуется на преодоление тягового сопротивления орудия, сопротивления передвижению и потерь на буксование. "
          "У фрезы основная доля мощности передаётся через вал отбора мощности на ротор, а движители лишь перемещают "
          "агрегат, причём реакция почвы на ножи ротора частично создаёт толкающее усилие.")
    doc.p("Тяговое сопротивление рабочих органов, перемещающих почву, описывается рациональной формулой В. П. Горячкина "
          "[@goryachkin1965], в которой выделяются составляющие трения, деформации пласта и сообщения ему кинетической "
          "энергии. Для лаповых культиваторов при постоянной глубине обычно используют её упрощённую форму, в которой "
          "удельное сопротивление на единицу площади поперечного сечения обрабатываемого слоя линейно зависит от квадрата "
          "скорости [@sineokov1977]. Для фрез энергоёмкость процесса характеризуют удельной работой на единицу объёма "
          "обработанной почвы; при постоянной частоте вращения ротора она зависит от подачи на нож и, следовательно, от "
          "поступательной скорости агрегата [@sineokov1977]. Эмпирические зависимости тягового сопротивления и мощности "
          "для широкого класса орудий собраны в стандарте ASABE D497 [@asabe_d497].")
    doc.p("Тягово-сцепные свойства колёсного трактора характеризуются кривой буксования – зависимостью буксования движителей "
          "от коэффициента использования сцепного веса [@guskov1988,kutkov2004]. При одной и той же силе тяги буксование "
          "тем больше, чем меньше сцепной вес. Отсюда следует важное для сравнения обстоятельство: электротрактор, "
          "масса которого из-за батареи больше массы дизельного аналога, при равном тяговом сопротивлении орудия работает "
          "с меньшим буксованием, тогда как больший вес увеличивает сопротивление передвижению и давление движителей на "
          "почву. Воздействие движителей на почву [@ksenevich1985] зависит и от массы машины, и от буксования; в настоящей "
          "работе в число сравниваемых показателей включено буксование, а давление на почву не оценивалось (это "
          "ограничение работы указано в заключении).")
    doc.p("Тяговый электропривод с асинхронным двигателем и частотным регулированием [@voldek2008] отличается от "
          "дизельного двигателя формой характеристики: в зоне постоянного момента двигатель развивает номинальный момент "
          "начиная с нулевой частоты вращения, а выше номинальной частоты работает в зоне постоянной мощности. Предельная "
          "мощность ограничивается преобразователем частоты по току, а допустимая продолжительность работы – нагревом двигателя. Для "
          "испытуемой машины изготовитель указывает мощность 18,4 кВт в 30-минутном режиме и 12 кВт в часовом режиме "
          "[@jinma_yl], т. е. мощности кратковременных режимов работы двигателя. Поэтому при сравнении с "
          "дизельным трактором необходимо различать режимы, допустимые кратковременно и в течение часа и более.")

    doc.h2("1.3", "Нормативные методы оценки сельскохозяйственной техники и их применимость к электротракторам")
    doc.p("Испытания сельскохозяйственной техники в государствах – участниках межгосударственной стандартизации "
          "регламентированы комплексом стандартов. Условия испытаний (твёрдость, влажность, рельеф, засорённость и "
          "т. п.) определяют по ГОСТ 20915 [@gost20915]; агротехническую оценку машин для поверхностной и мелкой обработки почвы – "
          "по ГОСТ 33687 [@gost33687] с учётом требований к качеству предпосевной обработки ГОСТ 26244 [@gost26244]; "
          "эксплуатационно-технологическую оценку – по ГОСТ 24055 [@gost24055]; энергетическую "
          "оценку – по ГОСТ 34631 [@gost34631]; экономическую – по ГОСТ 34393 [@gost34393]; испытания тракторов – по "
          "ГОСТ 7057 [@gost7057].")
    doc.p("Анализ этих документов применительно к электротрактору выявляет три пробела. Первый: ГОСТ 34631 ориентирован "
          "на машины с двигателями внутреннего сгорания, основным энергетическим показателем в нём является расход топлива, "
          "а методы определения расхода электроэнергии из бортового накопителя и приведения её к первичной энергии не "
          "установлены. Второй: при эксплуатационно-технологической оценке по ГОСТ 24055 продолжительность заправки "
          "дизельного трактора топливом мала по сравнению со временем смены, тогда как продолжительность зарядки батареи "
          "электротрактора соизмерима со временем работы и становится определяющим ограничением сменной выработки; "
          "порядок учёта такого времени стандартом не установлен. Третий: ГОСТ 34393 "
          "предусматривает сравнение по совокупности экономических показателей, но не по совокупности разнородных "
          "показателей, среди которых экономические – лишь одна группа.")
    doc.p("Зарубежная практика эксплуатации машинно-тракторного парка опирается на стандарты ASABE EP496 и D497 "
          "[@asabe_ep496,asabe_d497], содержащие, в частности, зависимость удельного объёмного расхода дизельного топлива "
          "от загрузки двигателя, полученную обобщением результатов испытаний тракторов в Небраске [@grisso2004]. Эта "
          "зависимость позволяет оценить расход топлива дизельного трактора, если известна потребная мощность, и "
          "используется в настоящей работе для построения расчётной модели дизельного аналога; поскольку она получена "
          "преимущественно для тракторов большой мощности, её применимость к дизелю малой мощности учтена поправочным "
          "коэффициентом с диапазоном вариации (подраздел 4.1).")
    doc.p("Отдельную проблему составляет приведение электрической и топливной энергии к сопоставимому виду. Энергия, "
          "подведённая к машине (электроэнергия из сети, теплота сгорания топлива), характеризует машину, но не "
          "учитывает потерь при производстве энергоносителя. Для учёта последних применяют коэффициенты пересчёта в первичную энергию "
          "[@eu2012,jec2020]. Аналогично для выбросов CO_{2} различают выбросы в месте работы машины и выбросы с "
          "учётом производства электроэнергии [@ipcc2006,abb2025]. В работе используются обе формы показателей.")

    doc.h2("1.4", "Методы многокритериальной сравнительной оценки")
    doc.p("Сравнение машин по совокупности показателей относится к задачам многокритериального выбора [@zeleny1982,hwang1981]. "
          "Наиболее распространён метод аддитивной свёртки, в котором нормированные значения показателей суммируются с "
          "весовыми коэффициентами. Результат свёртки определяется тремя элементами, которые выбирает исследователь: способом "
          "нормирования, способом назначения весовых коэффициентов и составом показателей.")
    doc.p("Способ нормирования. Нормирование по отношению к базовому образцу (q = x_{ЭТ}/x_{Д}) естественно для "
          "испытаний, но неограниченно: при x_{ЭТ} = 0 (выбросы в месте работы) или x_{Д} → 0 отношение теряет смысл и "
          "один показатель подавляет остальные. Нормирование по размаху значений (min–max) зависит от набора сравниваемых "
          "альтернатив. В настоящей работе использована нормированная разность значений показателя двух машин, ограниченная интервалом "
          "[−1; 1] и не зависящая от набора альтернатив (подраздел 4.7).")
    doc.p("Способ назначения весовых коэффициентов. Метод анализа иерархий Т. Саати [@saaty1980,saaty1993] формализует экспертные суждения "
          "через матрицы парных сравнений и позволяет проверить их согласованность. Энтропийный метод [@hwang1981,zeleny1982] "
          "назначает веса по информативности показателя: показатель, значения которого мало различаются у сравниваемых "
          "альтернатив, получает малый вес. Экспертные веса отражают цели оценки, но субъективны; энтропийные объективны, "
          "но не учитывают значимость. Комбинирование обоих способов и последующая проверка устойчивости результата "
          "к вариации весов снижают влияние субъективности.")
    doc.p("Состав показателей. Повторный учёт одного эффекта в нескольких показателях увеличивает его влияние на "
          "результат свёртки: например, ограниченный запас энергии электротрактора уменьшает сменную выработку и "
          "одновременно увеличивает затраты труда на 1 га, если оплачивается время ожидания зарядки. В работе время "
          "ожидания зарядки не оплачивается (допущение), а связанные показатели (подведённая и первичная энергия, прямые "
          "и совокупные затраты, выбросы с учётом производства электроэнергии и в месте работы) отнесены к одной группе, "
          "совместный вес которой задаётся весом группы (подраздел 4.6).")
    doc.p("Для контроля результата аддитивной свёртки используют методы иной природы, в частности TOPSIS "
          "[@hwang1981], ранжирующий альтернативы по относительной близости к идеальному решению. Поскольку оба метода "
          "используют одни и те же показатели и весовые коэффициенты, совпадение их выводов не является независимым "
          "подтверждением, но показывает, что вывод не определяется способом свёртки.")

    doc.h2("1.5", "Выводы по разделу и задачи исследования")
    doc.p("Анализ состояния вопроса позволяет сделать следующие выводы:")
    doc.bullets([
        "энергетическое преимущество электрической тяги подтверждено преимущественно моделированием тракторов средней и большой мощности; полевые данные по электротракторам тягового класса 0,6 с серийными орудиями ограничены",
        "действующие стандарты на энергетическую и экономическую оценку разработаны для машин с двигателями внутреннего сгорания и не содержат процедуры сопоставления машин с различными энергоносителями",
        "ограничение запаса энергии на борту электротрактора должно учитываться как самостоятельный фактор, зависящий от организации работ, а не только от свойств машины",
        "результат многокритериальной оценки зависит от нормирования, весов и состава показателей, поэтому вывод о преимуществе должен сопровождаться оценкой его устойчивости",
    ])
    doc.p("Исходя из этого, сформулированы задачи исследования, приведённые во введении. Их решение изложено в "
          "разделах 2–6: методика и условия испытаний (раздел 2), результаты испытаний (раздел 3), методика "
          "сравнительной оценки (раздел 4), её результаты (раздел 5) и зоны оптимального использования (раздел 6).")
